import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇787｜超脱者与制度·超脱者与共生法院的关系","description":"","frontmatter":{"title":"篇787｜超脱者与制度·超脱者与共生法院的关系","no":787,"module":4,"tags":["超脱","制度","共生法院","司法","法律面前人人平等"],"related":["48-司法体系与裁决机制","40-共生宪法总纲","784-超脱者与制度总论"]},"headers":[],"relativePath":"zh/787_模块4-制度-超脱者与共生法院.md","filePath":"zh/787_模块4-制度-超脱者与共生法院.md"}'),e={name:"zh/787_模块4-制度-超脱者与共生法院.md"};function i(n,t,s,u,h,q){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇787-超脱者与制度·超脱者与共生法院的关系" tabindex="-1">篇787｜超脱者与制度·超脱者与共生法院的关系 <a class="header-anchor" href="#篇787-超脱者与制度·超脱者与共生法院的关系" aria-label="Permalink to &quot;篇787｜超脱者与制度·超脱者与共生法院的关系&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档48、40、784</p></blockquote><h2 id="引言-最强的人-也得站在被告席上" tabindex="-1">引言：最强的人，也得站在被告席上 <a class="header-anchor" href="#引言-最强的人-也得站在被告席上" aria-label="Permalink to &quot;引言：最强的人，也得站在被告席上&quot;">​</a></h2><p>共生法院是锚点共生文明的司法机构——审理一切违反万族法律的案件。旧世界的超脱者从来不进法院，因为他最强，法院管不着他。衡元宙必须正面回答：<strong>一个强到衡锚超多元境的人，能不能站在被告席上？</strong> 答案是：能，而且必须能。本篇把超脱者与共生法院的关系钉死。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求法院直接审判掠夺行为；万族共和公理要求法院对万族平等；集体升维公理要求司法公正服务于升维；因果自律公理要求司法过程不扰动因果；法则优先公理要求司法程序自洽、不可被超脱者个人绕过。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、超脱者在法院的双重身份" tabindex="-1">一、超脱者在法院的双重身份 <a class="header-anchor" href="#一、超脱者在法院的双重身份" aria-label="Permalink to &quot;一、超脱者在法院的双重身份&quot;">​</a></h2><p>超脱者在共生法院里有双重身份：</p><ol><li><strong>公民身份</strong>：超脱者作为万族公民，受万族法律管辖。他违法，法院审理他</li><li><strong>证人身份</strong>：超脱者因为阿赖耶网络的全量记录能力，可以在他人案件中作为事实证人提供因果证据</li></ol><p>两种身份不能混淆：超脱者不能因为&quot;我是证人&quot;就免于被起诉，也不能因为&quot;我是超脱者&quot;就拒绝作证。</p><h2 id="二、超脱者案件的特殊程序" tabindex="-1">二、超脱者案件的特殊程序 <a class="header-anchor" href="#二、超脱者案件的特殊程序" aria-label="Permalink to &quot;二、超脱者案件的特殊程序&quot;">​</a></h2><p>超脱者案件因为被告破坏力极大，有特殊程序，但这个程序是<strong>更严格</strong>而不是更宽松：</p><ul><li><strong>合议庭升级</strong>：超脱者案件必须由最高合议庭审理，不能由基层法院独任审理</li><li><strong>全程公开</strong>：超脱者案件的全部庭审过程通过阿赖耶网络全程直播，万族一切生灵可旁听</li><li><strong>上级复核</strong>：一审判决后，必须经上级法院复核才能生效</li><li><strong>执行隔离</strong>：判决生效后，执行阶段采取隔离措施，防止超脱者在执行过程中扰动位面</li></ul><p>特殊程序的逻辑是：<strong>超脱者破坏力大，所以审判他要更谨慎、更公开、更有保障。</strong> 不是&quot;超脱者法外开恩&quot;，而是&quot;超脱者法内严审&quot;。</p><h2 id="三、超脱者不能干预法院" tabindex="-1">三、超脱者不能干预法院 <a class="header-anchor" href="#三、超脱者不能干预法院" aria-label="Permalink to &quot;三、超脱者不能干预法院&quot;">​</a></h2><p>最硬的一条：<strong>超脱者不能干预法院。</strong></p><ul><li>不能因为&quot;我实力强&quot;就要求法院轻判</li><li>不能因为&quot;我是为你好&quot;就要求法院撤诉</li><li>不能因为&quot;我能影响因果&quot;就要求法院延期</li></ul><p>任何干预法院的行为，本身就是新的犯罪——&quot;干扰司法独立&quot;罪，由更高一级法院审理。这一条确保法院始终是万族的司法机关，不是超脱者的私人法庭。</p><h2 id="四、法院对超脱者的判决类型" tabindex="-1">四、法院对超脱者的判决类型 <a class="header-anchor" href="#四、法院对超脱者的判决类型" aria-label="Permalink to &quot;四、法院对超脱者的判决类型&quot;">​</a></h2><p>法院对超脱者的判决，按情节轻重分五级：</p><ol><li><strong>警告</strong>：轻微违规，书面警告，记录在案</li><li><strong>赔偿</strong>：造成因果损害，向受害方赔偿本源增量</li><li><strong>降级</strong>：法则锚定权限降级，部分公共算力收回</li><li><strong>暂停</strong>：暂停超脱者岗位，停职检查</li><li><strong>除名</strong>：取消超脱者资格，按普通公民对待</li></ol><p>五级判决确保司法既有牙齿，又有梯度。超脱者不是&quot;一审就杀&quot;，而是&quot;一级一级来&quot;。</p><p>判决之后还有执行问题。普通修炼者不服从判决，法院可以强制；但超脱者如果拒不履行赔偿、不接受轮岗降级，共生法院不能靠&quot;打一架&quot;来执行——那等于回到了掠夺逻辑。衡元宙的解法是&quot;权重执行&quot;：法院判决一旦生效，阿赖耶网络自动调整该超脱者的文明权重，冻结其跨位面调动权限，降级其法则锚定操作级别，直到他履行判决为止。换句话说，不需要谁去强制他，系统会让他&quot;做不下去&quot;。如果他试图切断与阿赖耶网络的连接来逃避执行，那本身就是一级重罪，锚点监督委员会将启动联合调查。这种&quot;不靠武力靠系统&quot;的执行方式，才是法院对最强者真正有牙齿的地方。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：旧世界让最强者逃避审判，等于让掠夺行为不受惩罚；衡元宙用法院把掠夺者送上被告席</li><li><strong>反掠夺</strong>：法院直接审判掠夺行为，掠夺派超脱者在法律面前无处遁形</li><li><strong>唐罗上限对比</strong>：唐罗在他的位面就是法律；衡元宙要求唐罗站在被告席上接受审判</li><li><strong>万族全覆盖</strong>：法院对万族一切生灵平等管辖，超脱者不能例外</li><li><strong>超多元全开放</strong>：超脱者案件全程公开、判决全文通过无私道全网开放。判决结果直接影响其文明权重</li><li><strong>全员无限均等</strong>：众生全员无限均等法则——锚点共生文明内人人自带基础无限之力，佛系懒狗保有保底基础无限、不被时代淘汰，卷王少年至尊可叠加更高层级无限；无限本源人人自带，掠夺自然失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>最强的人，也得站在被告席上。这不是对超脱者的不信任，是对司法独立的尊重。一个连超脱者都能审判的法院，才是万族真正的法院。如果法院只能审普通人，审不了最强者，那它不是法院，是给弱者准备的祠堂。共生法院的判决不受任何超脱者的实力影响，只受证据和法律影响——这就是衡元宙对&quot;法律面前人人平等&quot;最硬的一次执行。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./48-司法体系与裁决机制.html">48-司法体系与裁决机制</a> · <a href="./40-共生宪法总纲.html">40-共生宪法总纲</a> · <a href="./784_模块4-制度-总论.html">784-超脱者与制度总论</a> · <a href="./780_模块4-万族-超脱者的监督机制.html">780-超脱者的监督机制</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',29)])])}const p=o(e,[["render",i]]);export{_ as __pageData,p as default};
